const capPendingApprovalFor = `-- name: CapPendingApprovalFor :one
SELECT a.id, a.invocation_id, i.trace_id
FROM cap_approvals a
JOIN cap_invocations i ON i.tenant_id = a.tenant_id AND i.invocation_id = a.invocation_id
WHERE a.tenant_id = $1 AND a.capability = $2 AND a.account_id = $3 AND a.arguments_digest = $4 AND a.action_key = $5 AND a.status = 'pending'
LIMIT 1
`

type CapPendingApprovalForParams struct {
	TenantID        string
	Capability      string
	AccountID       int64
	ArgumentsDigest string
	ActionKey       string
}

type CapPendingApprovalForRow struct {
	ID           int64
	InvocationID string
	TraceID      string
}

func (q *Queries) CapPendingApprovalFor(ctx context.Context, arg CapPendingApprovalForParams) (CapPendingApprovalForRow, error) {
	row := q.db.QueryRow(ctx, capPendingApprovalFor,
		arg.TenantID,
		arg.Capability,
		arg.AccountID,
		arg.ArgumentsDigest,
		arg.ActionKey,
	)
	var i CapPendingApprovalForRow
	err := row.Scan(&i.ID, &i.InvocationID, &i.TraceID)
	return i, err
}

